let points = new ArrayList();
let mouspeedX=0;
let mouspeedY=0;

function setup(){
  createCanvas(1112, 834);
  background(125);
  smooth();
}

function draw(){
   // fill(255,10);
   // rect(0,0,width,height);
   for(c=points.size()-1; c>=0; c--){
    let p = (Point)points.get(c);
     if(p.done){ points.remove(c);}
     else{  
     p.findNN();
     p.update();  }
  }
 // println(points.size());
}

function mouseDragged(){
   mouspeedX=  ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - mouspeedX)/(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)));
   mouspeedY=  ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - mouspeedY)/(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)));

  //let shift =random(-10,10);
  //let speed = mouspeedX/2;//random(1.2,2.5);
  let col = color(255,48);
  for( i=.5; i<1.5; i+=.5){ //.1
    for( c=0; c<360; c+=60){ //+10
      let xv=cos(radians(c+mouspeedX))*mouspeedX*i/3; // cos(radians(c+shift))*speed*i/3 c t
      let yv=sin(radians(c+mouspeedY))*mouspeedY*i/3;
      let from, to, speed;
      to= new PVector ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
      from= new PVector ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
      speed= new PVector (xv,yv);
      points.add( new Point(from,speed, col, to , 10 ) );
    }
  }
}

class Point {
  let x,y,xv,yv, disto =random(10,13);
  r= 4;
  from, to, speed;
  shrinkRate;
  done = false;
  timer = 2;
  let c;// = color(random(200,255), 100,0,48);
  //let sordist;

  constructor(from, speed, c, to, disto){ 
    this.from= from;
    this.speed= speed; 
   // this.shrinkRate = random(.995,.999);
    this.c = c;
    this.to= to; 
  }

 function findNN(){
   let mindist=999;
   //let closestp;
   for (c=points.size()-1; c>=0; c--){ 
       let q = (Point)points.get(c);
       let dist=sqrt( sq(this.from.x - q.from.x)+sq(this.from.y -q.from.y)) ;
      // this.sordist[c]= dist;
    if(dist < mindist && dist>0) {
      mindist=dist;
      this.to.x=q.from.x; 
      this.to.y=q.from.y; 
      this.disto=mindist;
    }
   }
   // this.sortdist.sort()
   // idx= for... dist == sortdist // should return a bool or idx
 }

  function update(){
     this.shrinkRate =  .999+(cos(timer*10))/100 ;//random(.995,.999);
    if(this.r>0){ this.r *= shrinkRate;}
      this.speed.mult(1); //.999
      this.speed.x += random(-.02,.015);
      this.speed.y += random(-.02,.015);
      this.speed.x += sqrt(this.disto)/1000;
      this.speed.y += sqrt(this.disto)/1000;

    timer -= .01;//random(.01,.1);
    if(timer <= 0){
      this.done = true;
    }
    //this.xv = noise(this.x*.02-PI/4,this.y*.02)*2-1;
    this.from.add(this.speed);
   // fill( (this.speed.x + this.speed.y)*100, this.speed.x*100, this.speed.y*200 ,64); // 
    //fill(50,1);
    //stroke(c);//255,48);
    strokeWeight(.1);
    //ellipse(this.from.x,this.from.y,this.r,this.r); // ellipse(this.to.x,this.from.y,this.r,this.r);
    stroke( ((this.speed.x) + (this.speed.y))*300, this.speed.x*800, this.speed.y*800 ,64); // 
    line(this.from.x,this.from.y, this.to.x, this.to.y);  
  }
}

